<script>
function printerManager(){return{openCreate:false,discovered:[],selectedName:'',notice:'',async discover(){this.notice='Menghubungkan ke Local Print Agent...';try{const c=await fetch('{{ route('printer.agent-config') }}').then(r=>r.json());const r=await fetch(c.url,{headers:c.headers});if(!r.ok)throw new Error();this.discovered=await r.json();this.notice=this.discovered.length?'Pilih printer untuk mengisi device identifier.':'Tidak ada printer yang ditemukan.';}catch(e){this.notice='Local Print Agent belum terhubung. Pair printer di Windows lalu jalankan agent.';}},useDiscovered(p){this.selectedName=p.name;this.openCreate=true;this.notice='Device '+p.name+' dipilih.';},async testPrinter(id){this.notice='Menyiapkan test print...';let job=null;try{const r=await fetch('{{ url('/settings/printers') }}/'+id+'/test',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'}});const d=await r.json();job=d.job;const p=d.package;const sent=await fetch(p.url,{method:'POST',headers:p.headers,body:p.body});if(!sent.ok)throw new Error();this.notice='Test print berhasil dikirim.';}catch(e){if(job)fetch('{{ url('/print-jobs') }}/'+job+'/status',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({status:'FAILED',error_message:'Local Print Agent tidak tersedia.'})});this.notice='Printer tidak tersedia. Job gagal tercatat; gunakan Coba lagi atau Cetak via Browser.';}}}}
</script>
